SET @prov_c='%s';
SET @id:= '%s';
SET @cat_id := '%s';
SET @send :=  IF((SELECT active FROM sys_report WHERE cat_id = @cat_id and id = @id )=1,0,2);
SET @b_year:=(SELECT variable FROM sys_variables WHERE vname = 'year_student');
SET @start_d:=concat(@b_year-1,'1001');
SET @end_d:=concat(@b_year,'0930');

CREATE TABLE IF NOT EXISTS s_school4 (
  id varchar(32) NOT NULL,
  hospcode varchar(5) NOT NULL,
	schoolid varchar(10) NOT NULL,
  areacode varchar(8) NOT NULL,
  flag_sent varchar(1) DEFAULT NULL,
  date_com varchar(14) DEFAULT NULL,
  b_year varchar(4) NOT NULL,
	target int(10) DEFAULT 0,
	result int(10) DEFAULT 0,
PRIMARY KEY (id,hospcode,areacode,b_year,schoolid),
	KEY (hospcode),
	KEY (areacode),
	KEY (b_year),
	KEY (schoolid)
	
) ENGINE=MyISAM DEFAULT CHARSET=utf8;

DELETE FROM s_school4  WHERE id=@id AND b_year=(@b_year+543);
INSERT IGNORE INTO s_school4  
(
SELECT
@id,h.hoscode
,s.schoolid
,s.SUBDISTRICTCODE areacode
,@send,DATE_FORMAT(now(),'%Y%m%d%H%i') as d_com
,@b_year+543 as b_year
,COUNT(DISTINCT s.schoolid) as target
,COUNT(DISTINCT IF(ISNULL(s.hospcode),s.schoolid,NULL)) as result
FROM school s INNER JOIN s_school3 s3 ON s.schoolid=s3.schoolid
LEFT JOIN chospital h ON s.hospcode = h.hoscode
WHERE SUBSTR(s.SUBDISTRICTCODE,1,2) IN(@prov_c)
GROUP BY s.SUBDISTRICTCODE,s.hospcode,s.schoolid
);

DELETE t FROM s_school4 t LEFT JOIN s_school3 r ON t.SchoolID=r.SchoolID AND t.b_year=r.b_year WHERE ISNULL(r.SchoolID);
